import React, { useState, useEffect, useContext } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order3.jpg";
import "..UpdateOrder.css"; // Ensure you import the CSS file

const UpdateOrder = () => {
  const { id } = useParams(); // Get order ID from URL parameters
  const navigate = useNavigate();
  const { setOrdersChanged } = useContext(OrderContext); // Context for triggering re-render after updating order

  const [loading, setLoading] = useState(true); // To show loading state
  const [error, setError] = useState(null); // To handle errors if any occur
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  // Fetch the order details when the component mounts or the `id` changes
  useEffect(() => {
    const fetchOrderDetails = async () => {
      setLoading(true);
      try {
        const response = await axios.get(`http://localhost:5000/orders/${id}`);
        // Handle the fetched data and update the state
        if (response.data) {
          setOrderData({
            firstName: response.data.firstName || "",
            lastName: response.data.lastName || "",
            email: response.data.email || "",
            phoneNumber: response.data.phoneNumber || "",
            address: response.data.address || "",
            city: response.data.city || "",
            orderId: response.data.orderId || "",
            specialInstructions: response.data.specialInstructions || "",
            pickupTime: response.data.pickupTime || "",
            orderStatus: response.data.orderStatus || "",
          });
        } else {
          setError("Order not found.");
        }
      } catch (err) {
        setError("Failed to fetch order details. Please try again.");
      } finally {
        setLoading(false);
      }
    };

    // Only fetch order details if `id` is valid
    if (id) {
      fetchOrderDetails();
    }
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setOrderData((prevData) => ({ ...prevData, [name]: value }));
  };

  const updateOrder = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/orders/${id}`, orderData);
      setOrdersChanged((prev) => !prev); // Trigger re-render to update order list
      alert("✅ Order Updated Successfully!");
      navigate("/all-orders"); // Redirect to the all orders page after successful update
    } catch (err) {
      console.error("Update Order Error:", err);
      alert("❌ Failed to update order. Please try again.");
    }
  };

  if (loading) return <div className="loading-message">Loading...</div>;
  if (error) return <div className="error-message">{error}</div>;

  return (
    <div className="update-order-container">
      <div className="update-order-form-container">
        <h2>Update Order</h2>
        <form onSubmit={updateOrder}>
          {["firstName", "lastName", "email", "phoneNumber", "address", "city", "orderId", "specialInstructions", "pickupTime", "orderStatus"].map((field) => (
            <div key={field} className="form-field">
              <label htmlFor={field}>
                {field.replace(/([A-Z])/g, " $1").trim()}
              </label>
              <input
                type={field === "email" ? "email" : field === "phoneNumber" ? "tel" : "text"}
                id={field}
                name={field}
                value={orderData[field] || ""}
                onChange={handleChange}
                required
              />
            </div>
          ))}
          <div className="button-container">
            <button type="submit">Update Order</button>
            <button type="button" onClick={() => navigate("/all-orders")}>Cancel</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default UpdateOrder;
